import{Ct as e,ct as t,lt as n,q as r}from"./chunks/framework.BVmwMUcr.js";var i=JSON.parse(`{"title":"Suishi Village","description":"An introduction to Suishi Village","frontmatter":{"lang":"en-US","title":"Suishi Village","description":"An introduction to Suishi Village","llm_translated":true},"headers":[],"relativePath":"en/infra/hemc/suishi.md","filePath":"en/infra/hemc/suishi.md","lastUpdated":1791510705000}`),a={name:`en/infra/hemc/suishi.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /en/infra/hemc/suishi.md for this page in Markdown format</div><h1 id="suishi-village" tabindex="-1">Suishi Village <a class="header-anchor" href="#suishi-village" aria-label="Permalink to “Suishi Village”">​</a></h1><p>Suishi Village sits right next to University Town Campus — walk straight along the road between the Library and the A1 teaching building for about 3 minutes and you reach it right outside the school gate. It is a great place for everyday meals out and shopping.</p><h2 id="dining" tabindex="-1">Dining <a class="header-anchor" href="#dining" aria-label="Permalink to “Dining”">​</a></h2><ul><li><strong>Noodles/rice</strong>: Zhenya Beef Noodles, Longjiang Pork Knuckle Rice</li><li><strong>Full meals/group dinners</strong>: Beidiaor&#39;er Copper Pot Chicken, Northeastern Chinese food, Wuhan stir-fry, Xianmiao Roast Chicken, chicken pot (jigongbao)</li><li><strong>Drinks</strong>: Mixue, ChaPanda, Lucky Cup</li></ul><h2 id="daily-shopping" tabindex="-1">Daily Shopping <a class="header-anchor" href="#daily-shopping" aria-label="Permalink to “Daily Shopping”">​</a></h2><p>Suishi Village has privately run supermarkets slightly larger than the on-campus Xiya Xing&#39;an Comprehensive Supermarket, but no large chain supermarkets like RT-Mart or Walmart. Everyday fruit, snacks, and sundries can all be bought here.</p><h2 id="transit-connections" tabindex="-1">Transit Connections <a class="header-anchor" href="#transit-connections" aria-label="Permalink to “Transit Connections”">​</a></h2><p>To return to campus from Suishi Village, enter through the <strong>East Gate</strong>. Getting to the metro station requires crossing the entire teaching area, so compared with going to University Town South Station from West Gate 1 of the living area, Suishi Village is not particularly convenient for metro access.</p><h2 id="rentals" tabindex="-1">Rentals <a class="header-anchor" href="#rentals" aria-label="Permalink to “Rentals”">​</a></h2><p>Suishi Village has rooms available for student renters, suitable for postgraduate exam preparation, internships, and similar situations. Students with relevant experience are welcome to add detailed rental advice.</p>`,11)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};